    private void enablePlayerListScrolling(
            Component component)
    {
        /*
         * Forward wheel movement from the player list and its
         * child components to the inner player scrollbar.
         *
         * The property marker prevents duplicate listeners from
         * being attached to persistent Swing components.
         */
        if (component instanceof javax.swing.JComponent)
        {
            javax.swing.JComponent swingComponent =
                    (javax.swing.JComponent) component;

            if (Boolean.TRUE.equals(
                    swingComponent.getClientProperty(
                            "wecorpcc.playerScrollInstalled"
                    )))
            {
                return;
            }

            swingComponent.putClientProperty(
                    "wecorpcc.playerScrollInstalled",
                    Boolean.TRUE
            );
        }

        component.addMouseWheelListener(
                event ->
                {
                    javax.swing.JScrollBar scrollBar =
                            playerScrollPane
                                    .getVerticalScrollBar();

                    if (!scrollBar.isVisible())
                    {
                        return;
                    }

                    int direction =
                            event.getWheelRotation();

                    int increment =
                            Math.max(
                                    18,
                                    scrollBar.getUnitIncrement(
                                            direction
                                    )
                            );

                    int maximumValue =
                            Math.max(
                                    scrollBar.getMinimum(),
                                    scrollBar.getMaximum() -
                                            scrollBar.getVisibleAmount()
                            );

                    int newValue =
                            scrollBar.getValue() +
                                    (direction * increment * 3);

                    scrollBar.setValue(
                            Math.max(
                                    scrollBar.getMinimum(),
                                    Math.min(
                                            newValue,
                                            maximumValue
                                    )
                            )
                    );

                    event.consume();
                }
        );

        if (component instanceof Container)
        {
            Container container =
                    (Container) component;

            for (Component child :
                    container.getComponents())
            {
                enablePlayerListScrolling(
                        child
                );
            }
        }
    }
