    public void clearDisplayedSpecs()
    {
        SwingUtilities.invokeLater(() ->
        {
            currentPlayerInfo.replaceAll(
                    (name, specs) -> ""
            );

            lastPlayerInfo.replaceAll(
                    (name, specs) -> ""
            );

            refreshPlayerDisplay();
        });
    }

    private void parseStatusHtml(
            String status)
    {
        String plainText =
                status
                        .replaceAll(
                                "(?i)<br\\s*/?>",
                                "\n"
                        )
                        .replaceAll(
                                "(?i)</?html>",
                                ""
                        )
                        .replaceAll(
                                "(?i)</?center>",
                                ""
                        )
                        .replaceAll(
                                "(?i)</?b>",
                                ""
                        )
                        .replaceAll(
                                "(?i)<font[^>]*>",
                                ""
                        )
                        .replaceAll(
                                "(?i)</font>",
                                ""
                        )
                        .replace(
                                "&nbsp;",
                                " "
                        )
                        .trim();

        String location =
                "At Corp";

        String kills =
                "0";

        String kph =
                "0";

        String trip =
                "0m 0s";

        String kill =
                "0s";

        String players =
                "0";

        List<String> extraLines =
                new ArrayList<>();

        for (String line :
                plainText.split("\\n"))
        {
            String cleanLine =
                    line.trim();

            if (cleanLine.isEmpty())
            {
                continue;
            }

            if (cleanLine.equalsIgnoreCase(
                    "At Corp"
            ) ||
                    cleanLine.equalsIgnoreCase(
                            "Waiting for Corp..."
                    ))
            {
                location =
                        cleanLine;
            }
            else if (cleanLine.startsWith(
                    "Kills:"
            ))
            {
                kills =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "KPH:"
            ))
            {
                kph =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Trip:"
            ))
            {
                trip =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Kill Time:"
            ))
            {
                kill =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Kill:"
            ))
            {
                kill =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Players:"
            ))
            {
                players =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else
            {
                extraLines.add(
                        cleanLine
                );
            }
        }

        setCompactStatus(
                location,
                kills,
                kph,
                trip,
                kill,
                players
        );

        if (extraLines.isEmpty())
        {
            statusLabel.setText("");
            statusLabel.setVisible(false);
        }
        else
        {
            statusLabel.setText(
                    "<html><center>" +
                            String.join(
                                    "<br>",
                                    extraLines
                            ) +
                            "</center></html>"
            );

            statusLabel.setVisible(true);
        }

        revalidate();
        repaint();
    }

    private String valueAfterColon(
            String text)
    {
        int index =
                text.indexOf(':');

        if (index < 0 ||
                index + 1 >= text.length())
        {
            return "";
        }

        return text
                .substring(index + 1)
                .trim();
    }

    private void setCompactStatus(
            String location,
            String kills,
            String kph,
            String trip,
            String kill,
            String players)
    {
        locationValueLabel.setText(
                location == null ||
                        location.trim().isEmpty()
                        ? "Waiting for Corp..."
                        : location
        );

        killsValueLabel.setText(
                emptyToDefault(
                        kills,
                        "0"
                )
        );

        kphValueLabel.setText(
                emptyToDefault(
                        kph,
                        "0"
                )
        );

        tripValueLabel.setText(
                emptyToDefault(
                        trip,
                        "0m 0s"
                )
        );

        killValueLabel.setText(
                emptyToDefault(
                        kill,
                        "0s"
                )
        );

        playersValueLabel.setText(
                emptyToDefault(
                        players,
                        "0"
                )
        );
    }

    private String emptyToDefault(
            String value,
            String defaultValue)
    {
        if (value == null ||
                value.trim().isEmpty())
        {
            return defaultValue;
        }

        return value.trim();
    }

    public void updatePlayers(
            Map<String, String> playerInfo,
            Set<String> lowHpPlayers,
            Set<String> lastKillAttendees,
            Map<String, Integer> killCounts,
            Set<String> hiddenPlayers)
    {
        SwingUtilities.invokeLater(() ->
        {
            long now =
                    System.currentTimeMillis();

            currentPlayerInfo.clear();
            currentLowHpPlayers.clear();
            currentLastKillAttendees.clear();

            if (playerInfo != null)
            {
                for (Map.Entry<String, String> entry :
                        playerInfo.entrySet())
                {
                    String displayName =
                            entry.getKey();

                    if (displayName == null ||
                            displayName.trim().isEmpty())
                    {
                        continue;
                    }

                    String normalizedName =
                            normalizeName(
                                    displayName
                            );

                    String specText =
                            entry.getValue() == null
                                    ? ""
                                    : entry.getValue();

                    currentPlayerInfo.put(
                            displayName,
                            specText
                    );

                    lastPlayerInfo.put(
                            normalizedName,
                            specText
                    );

                    displayNames.put(
                            normalizedName,
                            displayName
                    );

                    lastSeenAtCorp.put(
                            normalizedName,
                            now
                    );
                }
            }

            if (lowHpPlayers != null)
            {
                for (String name :
                        lowHpPlayers)
                {
                    currentLowHpPlayers.add(
                            normalizeName(name)
                    );
                }
            }

            if (lastKillAttendees != null)
            {
                for (String name :
                        lastKillAttendees)
                {
                    currentLastKillAttendees.add(
                            normalizeName(name)
                    );
                }
            }

            if (killCounts != null)
            {
                killCountReference =
                        killCounts;
            }

            if (hiddenPlayers != null)
            {
                hiddenPlayersReference =
                        hiddenPlayers;
            }

            refreshPlayerDisplay();
        });
    }

    private void refreshPlayerDisplay()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(
                    this::refreshPlayerDisplay
            );

            return;
        }

        /*
         * Save the current scrollbar position before rebuilding.
         *
         * Without this, the one-second AFK refresh can make
         * scrolling feel broken or jump back toward the top.
         */
        javax.swing.JScrollBar verticalBar =
                playerScrollPane
                        .getVerticalScrollBar();

        int previousScrollValue =
                verticalBar.getValue();

        playerListPanel.removeAll();

        List<PlayerRowData> activePlayers =
                new ArrayList<>();

        List<PlayerRowData> customerPlayers =
                new ArrayList<>();

        List<PlayerRowData> awayPlayers =
                new ArrayList<>();

        long now =
                System.currentTimeMillis();

        Set<String> allKnownPlayers =
                new HashSet<>();

        allKnownPlayers.addAll(
                displayNames.keySet()
        );

        allKnownPlayers.addAll(
                lastSeenAtCorp.keySet()
        );

        allKnownPlayers.addAll(
                customers.keySet()
        );

        for (String normalizedName :
                allKnownPlayers)
        {
            if (normalizedName == null ||
                    normalizedName.isEmpty())
            {
                continue;
            }

            if (isHidden(normalizedName))
            {
                continue;
            }

            String displayName =
                    displayNames.getOrDefault(
                            normalizedName,
                            normalizedName
                    );

            String cleanDisplayName =
                    removeYouSuffix(
                            displayName
                    );

            long lastSeen =
                    lastSeenAtCorp.getOrDefault(
                            normalizedName,
                            0L
                    );

            long awayDuration =
                    lastSeen <= 0
                            ? Long.MAX_VALUE
                            : now - lastSeen;

            boolean currentlyVisible =
                    isCurrentlyVisible(
                            normalizedName
                    );

            boolean isTemporarilyAway =
                    !currentlyVisible &&
                            lastSeen > 0 &&
                            awayDuration <
                                    AWAY_GRACE_PERIOD_MS;

            boolean isAway =
                    !currentlyVisible &&
                            lastSeen > 0 &&
                            awayDuration >=
                                    AWAY_GRACE_PERIOD_MS;

            boolean isCustomer =
                    customers.containsKey(
                            normalizedName
                    );

            boolean isLowHp =
                    currentLowHpPlayers.contains(
                            normalizedName
                    );

            int playerKills =
                    getPlayerKillCount(
                            normalizedName
                    );

            String specText =
                    getLastSpecText(
                            normalizedName
                    );

            PlayerRowData rowData =
                    new PlayerRowData(
                            normalizedName,
                            cleanDisplayName,
                            specText,
                            playerKills,
                            isLowHp,
                            isTemporarilyAway,
                            isAway,
                            lastSeen
                    );

            if (isCustomer)
            {
                customerPlayers.add(
                        rowData
                );
            }
            else if (isAway)
            {
                awayPlayers.add(
                        rowData
                );
            }
            else
            {
                activePlayers.add(
                        rowData
                );
            }
        }

        activePlayers.sort(
                Comparator
                        .comparing(
                                (PlayerRowData row) ->
                                        !row.lowHp
                        )
                        .thenComparing(
                                row ->
                                        row.displayName
                                                .toLowerCase()
                        )
        );

        customerPlayers.sort(
                Comparator.comparing(
                        row ->
                                row.displayName
                                        .toLowerCase()
                )
        );

        awayPlayers.sort(
                Comparator
                        .comparingLong(
                                (PlayerRowData row) ->
                                        row.lastSeen
                        )
                        .reversed()
        );

        addCategory(
                "Active Players",
                activePlayers,
                PlayerCategory.ACTIVE
        );

        addCategory(
                "Customers",
                customerPlayers,
                PlayerCategory.CUSTOMER
        );

        addCategory(
                "Away / AFK",
                awayPlayers,
                PlayerCategory.AWAY
        );

        updateHiddenButtonText();

        playerListPanel.revalidate();
        playerListPanel.repaint();

        playerScrollPane
                .getViewport()
                .revalidate();

        playerScrollPane
                .getViewport()
                .repaint();

        /*
         * Restore the previous position after Swing recalculates
         * the new scrollbar range.
         */
        SwingUtilities.invokeLater(() ->
        {
            int maximumValue =
                    Math.max(
                            verticalBar.getMinimum(),
                            verticalBar.getMaximum() -
                                    verticalBar.getVisibleAmount()
                    );

            verticalBar.setValue(
                    Math.max(
                            verticalBar.getMinimum(),
                            Math.min(
                                    previousScrollValue,
                                    maximumValue
                            )
                    )
            );
        });
    }

    private void addCategory(
            String title,
            List<PlayerRowData> players,
            PlayerCategory category)
    {
        boolean collapsed =
                isCategoryCollapsed(category);

        JPanel headerPanel =
                new JPanel(
                        new BorderLayout()
                );

        headerPanel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        headerPanel.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(
                                0,
                                0,
                                1,
                                0,
                                ColorScheme.MEDIUM_GRAY_COLOR
                        ),
                        BorderFactory.createEmptyBorder(
                                6,
                                7,
                                6,
                                7
                        )
                )
        );

        headerPanel.setMaximumSize(
                new Dimension(
                        Integer.MAX_VALUE,
                        32
                )
        );

        /*
         * Show a down arrow when expanded and a right arrow
         * when collapsed.
         */
        String arrow =
                collapsed
                        ? "▶ "
                        : "▼ ";

        JLabel categoryLabel =
                new JLabel(
                        arrow +
                                title.toUpperCase() +
                                "  (" +
                                players.size() +
                                ")"
                );

        categoryLabel.setForeground(
                getCategoryColor(category)
        );

        categoryLabel.setFont(
                categoryLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                11f
                        )
        );

        headerPanel.add(
                categoryLabel,
                BorderLayout.WEST
        );

        /*
         * Hand cursor shows users that the header is clickable.
         */
        headerPanel.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR
                )
        );

        categoryLabel.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR
                )
        );

        /*
         * Clicking either the header background or its text
         * collapses/expands the category.
         */
        MouseAdapter collapseListener =
                new MouseAdapter()
                {
                    @Override
                    public void mouseClicked(
                            MouseEvent event)
                    {
                        if (!SwingUtilities.isLeftMouseButton(event))
                        {
                            return;
                        }

                        toggleCategoryCollapsed(
                                category
                        );
                    }
                };

        headerPanel.addMouseListener(
                collapseListener
        );

        categoryLabel.addMouseListener(
                collapseListener
        );

        /*
         * Mouse-wheel scrolling still works over the header.
         */
        enablePlayerListScrolling(
                headerPanel
        );

        playerListPanel.add(
                headerPanel
        );

        playerListPanel.add(
                Box.createVerticalStrut(3)
        );

        /*
         * Stop here when the category is collapsed.
         * The header remains visible, but its player rows are hidden.
         */
        if (collapsed)
        {
            playerListPanel.add(
                    Box.createVerticalStrut(5)
            );

            return;
        }

        if (players.isEmpty())
        {
            JLabel emptyLabel =
                    new JLabel(
                            "No players"
                    );

            emptyLabel.setForeground(
                    SECONDARY_TEXT_COLOR
            );

            emptyLabel.setBorder(
                    BorderFactory.createEmptyBorder(
                            5,
                            10,
                            7,
                            2
                    )
            );

            enablePlayerListScrolling(
                    emptyLabel
            );

            playerListPanel.add(
                    emptyLabel
            );
        }
        else
        {
            for (PlayerRowData player : players)
            {
                playerListPanel.add(
                        createPlayerRow(
                                player,
                                category
                        )
                );

                playerListPanel.add(
                        Box.createVerticalStrut(2)
                );
            }
        }

        playerListPanel.add(
                Box.createVerticalStrut(8)
        );
    }

    private boolean isCategoryCollapsed(
            PlayerCategory category)
    {
        switch (category)
        {
            case CUSTOMER:
                return customersCollapsed;

            case AWAY:
                return awayPlayersCollapsed;

            case ACTIVE:
            default:
                return activePlayersCollapsed;
        }
    }

    private void toggleCategoryCollapsed(
            PlayerCategory category)
    {
        switch (category)
        {
            case CUSTOMER:
                customersCollapsed =
                        !customersCollapsed;
                break;

            case AWAY:
                awayPlayersCollapsed =
                        !awayPlayersCollapsed;
                break;

            case ACTIVE:
            default:
                activePlayersCollapsed =
                        !activePlayersCollapsed;
                break;
        }

        refreshPlayerDisplay();
    }

    private JPanel createPlayerRow(
            PlayerRowData player,
            PlayerCategory category)
    {
        JPanel row =
                new JPanel(
                        new GridBagLayout()
                );

        row.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        row.setBorder(
                BorderFactory.createEmptyBorder(
                        4,
                        5,
                        4,
                        3
                )
        );

        /*
         * Preserve the polished panel design and colors.
         * Only the row layout changes:
         * - KC is under the player name
         * - customer progress is centered on a full row underneath
         */
        int rowHeight =
                category == PlayerCategory.CUSTOMER
                        ? 76
                        : 58;

        row.setMaximumSize(
                new Dimension(
                        Integer.MAX_VALUE,
                        rowHeight
                )
        );

        Color circleColor =
                getPlayerCircleColor(
                        player,
                        category
                );

        /*
         * Column 1: status circle.
         */
        JLabel circleLabel =
                new JLabel("●");

        circleLabel.setForeground(
                circleColor
        );

        circleLabel.setFont(
                circleLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                14f
                        )
        );

        GridBagConstraints circleConstraints =
                new GridBagConstraints();

        circleConstraints.gridx = 0;
        circleConstraints.gridy = 0;
        circleConstraints.gridheight =
                category == PlayerCategory.CUSTOMER
                        ? 4
                        : 3;

        circleConstraints.anchor =
                GridBagConstraints.NORTHWEST;

        circleConstraints.insets =
                new Insets(
                        1,
                        0,
                        0,
                        5
                );

        row.add(
                circleLabel,
                circleConstraints
        );

        /*
         * Column 2: player name, KC, then status/details.
         *
         * KC is intentionally here instead of the far right so RuneLite
         * can never clip it on a narrow sidebar.
         */
        JPanel namePanel =
                new JPanel();

        namePanel.setLayout(
                new BoxLayout(
                        namePanel,
                        BoxLayout.Y_AXIS
                )
        );

        namePanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        JLabel nameLabel =
                new JLabel(
                        player.displayName
                );

        nameLabel.setForeground(
                NORMAL_TEXT_COLOR
        );

        nameLabel.setFont(
                nameLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                13f
                        )
        );

        JLabel kcLabel =
                new JLabel(
                        "KC " + player.kills
                );

        kcLabel.setForeground(
                category == PlayerCategory.CUSTOMER
                        ? CUSTOMER_COLOR
                        : NORMAL_TEXT_COLOR
        );

        kcLabel.setFont(
                kcLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                10f
                        )
        );

        JLabel detailsLabel =
                new JLabel(
                        buildSecondaryText(
                                player,
                                category
                        )
                );

        detailsLabel.setForeground(
                category == PlayerCategory.AWAY
                        ? AWAY_COLOR
                        : SECONDARY_TEXT_COLOR
        );

        detailsLabel.setFont(
                detailsLabel
                        .getFont()
                        .deriveFont(
                                Font.PLAIN,
                                9f
                        )
        );

        nameLabel.setAlignmentX(
                Component.LEFT_ALIGNMENT
        );

        kcLabel.setAlignmentX(
                Component.LEFT_ALIGNMENT
        );

        detailsLabel.setAlignmentX(
                Component.LEFT_ALIGNMENT
        );

        namePanel.add(nameLabel);
        namePanel.add(kcLabel);
        namePanel.add(detailsLabel);

        GridBagConstraints nameConstraints =
                new GridBagConstraints();

        nameConstraints.gridx = 1;
        nameConstraints.gridy = 0;
        nameConstraints.gridheight = 3;
        nameConstraints.weightx = 1.0;

        nameConstraints.fill =
                GridBagConstraints.HORIZONTAL;

        nameConstraints.anchor =
                GridBagConstraints.NORTHWEST;

        nameConstraints.insets =
                new Insets(
                        0,
                        0,
                        0,
                        3
                );

        row.add(
                namePanel,
                nameConstraints
        );

        /*
         * Column 3: special attacks.
         * Keep the polished design's spec column and colors.
         */
        String specText =
                player.specText == null ||
                        player.specText.trim().isEmpty()
                        ? ""
                        : player.specText;

        JLabel specLabel =
                new JLabel(
                        specText,
                        SwingConstants.CENTER
                );

        specLabel.setForeground(
                SECONDARY_TEXT_COLOR
        );

        specLabel.setFont(
                specLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                10f
                        )
        );

        specLabel.setPreferredSize(
                new Dimension(
                        52,
                        38
                )
        );

        specLabel.setMinimumSize(
                new Dimension(
                        42,
                        38
                )
        );

        specLabel.setMaximumSize(
                new Dimension(
                        58,
                        38
                )
        );

        GridBagConstraints specConstraints =
                new GridBagConstraints();

        specConstraints.gridx = 2;
        specConstraints.gridy = 0;
        specConstraints.gridheight = 3;

        specConstraints.anchor =
                GridBagConstraints.NORTHEAST;

        specConstraints.insets =
                new Insets(
                        0,
                        1,
                        0,
                        1
                );

        row.add(
                specLabel,
                specConstraints
        );

        /*
         * Customer progress bar:
         * own centered row across the usable player width.
         */
        JProgressBar packageProgressBar =
                new JProgressBar();

        packageProgressBar.setMinimum(0);
        packageProgressBar.setMaximum(1);
        packageProgressBar.setValue(0);

        packageProgressBar.setString("");
        packageProgressBar.setStringPainted(true);

        packageProgressBar.setBorderPainted(false);
        packageProgressBar.setFocusable(false);

        packageProgressBar.setPreferredSize(
                new Dimension(130, 17)
        );

        packageProgressBar.setMinimumSize(
                new Dimension(105, 17)
        );

        packageProgressBar.setMaximumSize(
                new Dimension(150, 17)
        );

        packageProgressBar.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        if (category == PlayerCategory.CUSTOMER)
        {
            CustomerPackage customerPackage =
                    customers.get(
                            player.normalizedName
                    );

            if (customerPackage != null &&
                    customerPackage.packageSize > 0)
            {
                int packageSize =
                        customerPackage.packageSize;

                int packageKills =
                        Math.min(
                                customerPackage.packageKills,
                                packageSize
                        );

                packageProgressBar.setMaximum(
                        packageSize
                );

                packageProgressBar.setValue(
                        packageKills
                );

                packageProgressBar.setString(
                        packageKills +
                                "/" +
                                packageSize
                );

                if (customerPackage.completed ||
                        packageKills >= packageSize)
                {
                    packageProgressBar.setForeground(
                            ACTIVE_COLOR
                    );
                }
                else
                {
                    packageProgressBar.setForeground(
                            CUSTOMER_COLOR
                    );
                }

                packageProgressBar.setVisible(true);
            }
            else
            {
                packageProgressBar.setVisible(false);
            }
        }
        else
        {
            packageProgressBar.setVisible(false);
        }

        GridBagConstraints progressConstraints =
                new GridBagConstraints();

        progressConstraints.gridx = 1;
        progressConstraints.gridy = 3;
        progressConstraints.gridwidth = 2;
        progressConstraints.weightx = 1.0;

        progressConstraints.anchor =
                GridBagConstraints.CENTER;

        progressConstraints.insets =
                new Insets(
                        4,
                        0,
                        0,
                        0
                );

        row.add(
                packageProgressBar,
                progressConstraints
        );

        /*
         * Right-click menu on every visible part.
         */
        installPlayerMenu(
                row,
                player.normalizedName
        );

        installPlayerMenu(
                circleLabel,
                player.normalizedName
        );

        installPlayerMenu(
                namePanel,
                player.normalizedName
        );

        installPlayerMenu(
                nameLabel,
                player.normalizedName
        );

        installPlayerMenu(
                kcLabel,
                player.normalizedName
        );

        installPlayerMenu(
                detailsLabel,
                player.normalizedName
        );

        installPlayerMenu(
                specLabel,
                player.normalizedName
        );

        installPlayerMenu(
                packageProgressBar,
                player.normalizedName
        );

        /*
         * Mouse wheel works over every part of this row.
         */
        enablePlayerListScrolling(
                row
        );

        return row;
    }

    private String buildSecondaryText(
            PlayerRowData player,
            PlayerCategory category)
    {
        if (category ==
                PlayerCategory.CUSTOMER)
        {
            CustomerPackage customerPackage =
                    customers.get(
                            player.normalizedName
                    );

            if (customerPackage == null)
            {
                return "Customer";
            }

            if (customerPackage.completed)
            {
                return "Package complete";
            }

            if (customerPackage.packageSize > 0)
            {
                int remaining =
                        Math.max(
                                0,
                                customerPackage.packageSize -
                                        customerPackage.packageKills
                        );

                return remaining +
                        " kills remaining";
            }

            return "Package size not set";
        }

        if (category ==
                PlayerCategory.AWAY)
        {
            long awayMilliseconds =
                    System.currentTimeMillis() -
                            player.lastSeen;

            return "AFK " +
                    formatAfkTime(
                            awayMilliseconds
                    );
        }

        /*
         * The player has left Corp but is still inside
         * the 90-second grace period.
         */
        if (player.temporarilyAway)
        {
            long awayMilliseconds =
                    System.currentTimeMillis() -
                            player.lastSeen;

            return "AFK " +
                    formatAfkTime(
                            awayMilliseconds
                    );
        }

        if (player.lowHp)
        {
            return "LOW HP";
        }

        if (currentLastKillAttendees.contains(
                player.normalizedName))
        {
            return "Attended last kill";
        }

        return "At Corp";
    }

    /*
     * Kept for compatibility with the earlier panel version.
     *
     * The current player rows use separate KC and package labels,
     * but this method remains available if another panel section
     * still calls it.
     */
    private String buildRightSideText(
            PlayerRowData player,
            PlayerCategory category)
    {
        if (category ==
                PlayerCategory.CUSTOMER)
        {
            CustomerPackage customerPackage =
                    customers.get(
                            player.normalizedName
                    );

            if (customerPackage != null &&
                    customerPackage.packageSize > 0)
            {
                return "<html><div style='text-align:right;'>" +
                        "<b>KC " +
                        player.kills +
                        "</b><br>" +
                        "<b>" +
                        customerPackage.packageKills +
                        "/" +
                        customerPackage.packageSize +
                        "</b>" +
                        "</div></html>";
            }
        }

        return "KC " +
                player.kills;
    }

    private Color getPlayerCircleColor(
            PlayerRowData player,
            PlayerCategory category)
    {
        if (category ==
                PlayerCategory.CUSTOMER)
        {
            return CUSTOMER_COLOR;
        }

        if (category ==
                PlayerCategory.AWAY)
        {
            return AWAY_COLOR;
        }

        if (player.lowHp)
        {
            return LOW_HP_COLOR;
        }

        return ACTIVE_COLOR;
    }

    private Color getCategoryColor(
            PlayerCategory category)
    {
        switch (category)
        {
            case CUSTOMER:
                return CUSTOMER_COLOR;

            case AWAY:
                return AWAY_COLOR;

            case ACTIVE:
            default:
                return ACTIVE_COLOR;
        }
    }

    private void installPlayerMenu(
            Component component,
            String normalizedName)
    {
        component.addMouseListener(
                new MouseAdapter()
                {
                    @Override
                    public void mousePressed(
                            MouseEvent event)
                    {
                        showPopupIfRequired(
                                event
                        );
                    }

                    @Override
                    public void mouseReleased(
