                    {
                        if (!event.isPopupTrigger())
                        {
                            return;
                        }

                        JPopupMenu menu =
                                createPlayerPopupMenu(
                                        normalizedName
                                );

                        menu.show(
                                event.getComponent(),
                                event.getX(),
                                event.getY()
                        );
                    }
                }
        );
