    public void removePlayer(String playerName)
    {
        String normalized =
                normalizeName(playerName);

        removedPlayers.add(normalized);
        players.remove(normalized);

        refreshAll();
        refreshPlayerDisplay();
    }

    private void confirmReset()
    {
        int choice = JOptionPane.showConfirmDialog(
                this,
                buildMassSummary(),
                "Reset Mass?",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.QUESTION_MESSAGE
        );

        if (choice != JOptionPane.YES_OPTION)
        {
            return;
        }

        if (resetCallback != null)
        {
            resetCallback.run();
        }

        resetPanel();
    }

    private String buildMassSummary()
    {
        return "Mass Summary\n\n" +
                "Trip Time: " + tripValue.getText() + "\n" +
                "Players Seen: " + playersSeen + "\n" +
                "Corp Kills: " + totalKills + "\n\n" +
                "Trip Specs\n" +
                "Fang: " + tripFangSpecs + "\n" +
                "Voidwaker: " + tripVoidwakerSpecs + "\n\n" +
                "Special Drops\n" +
                "Onyx: " + onyxCount + "\n" +
                "Arcane: " + arcaneCount + "\n" +
                "Spectral: " + spectralCount + "\n" +
                "Elysian: " + elysianCount + "\n\n" +
                "Reset this mass?";
    }

    public void resetPanel()
    {
        players.clear();
        removedPlayers.clear();

        massStartTime = 0;
        playersSeen = 0;
        totalKills = 0;

        currentFangSpecs = 0;
        currentVoidwakerSpecs = 0;
        currentDwhSpecs = 0;
        currentBgsDamage = 0;

        tripFangSpecs = 0;
        tripVoidwakerSpecs = 0;
        tripDwhSpecs = 0;
        tripBgsDamage = 0;

        onyxCount = 0;
        arcaneCount = 0;
        spectralCount = 0;
        elysianCount = 0;

        setMassActive(false);
        refreshAll();
