    private void parseStatusHtml(
            String status)
    {
        String plainText =
                status
                        .replaceAll(
                                "(?i)<br\\s*/?>",
                                "\n"
                        )
                        .replaceAll(
                                "(?i)</?html>",
                                ""
                        )
                        .replaceAll(
                                "(?i)</?center>",
                                ""
                        )
                        .replaceAll(
                                "(?i)</?b>",
                                ""
                        )
                        .replaceAll(
                                "(?i)<font[^>]*>",
                                ""
                        )
                        .replaceAll(
                                "(?i)</font>",
                                ""
                        )
                        .replace(
                                "&nbsp;",
                                " "
                        )
                        .trim();

        String location =
                "At Corp";

        String kills =
                "0";

        String kph =
                "0";

        String trip =
                "0m 0s";

        String kill =
                "0s";

        String players =
                "0";

        List<String> extraLines =
                new ArrayList<>();

        for (String line :
                plainText.split("\\n"))
        {
            String cleanLine =
                    line.trim();

            if (cleanLine.isEmpty())
            {
                continue;
            }

            if (cleanLine.equalsIgnoreCase(
                    "At Corp"
            ) ||
                    cleanLine.equalsIgnoreCase(
                            "Waiting for Corp..."
                    ))
            {
                location =
                        cleanLine;
            }
            else if (cleanLine.startsWith(
                    "Kills:"
            ))
            {
                kills =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "KPH:"
            ))
            {
                kph =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Trip:"
            ))
            {
                trip =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Kill Time:"
            ))
            {
                kill =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Kill:"
            ))
            {
                kill =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else if (cleanLine.startsWith(
                    "Players:"
            ))
            {
                players =
                        valueAfterColon(
                                cleanLine
                        );
            }
            else
            {
                extraLines.add(
                        cleanLine
                );
            }
        }

        setCompactStatus(
                location,
                kills,
                kph,
                trip,
                kill,
                players
        );

        if (extraLines.isEmpty())
        {
            statusLabel.setText("");
            statusLabel.setVisible(false);
        }
        else
        {
            statusLabel.setText(
                    "<html><center>" +
                            String.join(
                                    "<br>",
                                    extraLines
                            ) +
                            "</center></html>"
            );

            statusLabel.setVisible(true);
        }

        revalidate();
        repaint();
    }

    private String valueAfterColon(
            String text)
    {
        int index =
                text.indexOf(':');

        if (index < 0 ||
                index + 1 >= text.length())
        {
            return "";
        }

        return text
                .substring(index + 1)
                .trim();
    }

    private void setCompactStatus(
            String location,
            String kills,
            String kph,
            String trip,
