    private String emptyToDefault(
            String value,
            String defaultValue)
    {
        if (value == null ||
                value.trim().isEmpty())
        {
            return defaultValue;
        }

        return value.trim();
    }

    public void updatePlayers(
            Map<String, String> playerInfo,
            Set<String> lowHpPlayers,
            Set<String> lastKillAttendees,
            Map<String, Integer> killCounts,
            Set<String> hiddenPlayers)
    {
        SwingUtilities.invokeLater(() ->
        {
            long now =
                    System.currentTimeMillis();

            currentPlayerInfo.clear();
            currentLowHpPlayers.clear();
            currentLastKillAttendees.clear();

            if (playerInfo != null)
            {
                for (Map.Entry<String, String> entry :
                        playerInfo.entrySet())
                {
                    String displayName =
                            entry.getKey();

                    if (displayName == null ||
                            displayName.trim().isEmpty())
                    {
                        continue;
                    }

                    String normalizedName =
                            normalizeName(
                                    displayName
                            );

                    String specText =
                            entry.getValue() == null
                                    ? ""
                                    : entry.getValue();

                    currentPlayerInfo.put(
                            displayName,
                            specText
                    );

                    lastPlayerInfo.put(
                            normalizedName,
                            specText
                    );

                    displayNames.put(
                            normalizedName,
                            displayName
                    );

                    lastSeenAtCorp.put(
                            normalizedName,
                            now
                    );
                }
            }

            if (lowHpPlayers != null)
            {
                for (String name :
                        lowHpPlayers)
                {
                    currentLowHpPlayers.add(
                            normalizeName(name)
                    );
                }
            }

            if (lastKillAttendees != null)
            {
                for (String name :
                        lastKillAttendees)
                {
                    currentLastKillAttendees.add(
                            normalizeName(name)
                    );
                }
            }

            if (killCounts != null)
            {
                killCountReference =
                        killCounts;
            }

            if (hiddenPlayers != null)
            {
                hiddenPlayersReference =
                        hiddenPlayers;
            }

            refreshPlayerDisplay();
        });
    }

    private void refreshPlayerDisplay()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(
                    this::refreshPlayerDisplay
            );

            return;
        }

        /*
         * Save the current scrollbar position before rebuilding.
         *
         * Without this, the one-second AFK refresh can make
         * scrolling feel broken or jump back toward the top.
         */
        javax.swing.JScrollBar verticalBar =
                playerScrollPane
                        .getVerticalScrollBar();

        int previousScrollValue =
                verticalBar.getValue();

        playerListPanel.removeAll();

        List<PlayerRowData> activePlayers =
                new ArrayList<>();

        List<PlayerRowData> customerPlayers =
                new ArrayList<>();

        List<PlayerRowData> awayPlayers =
                new ArrayList<>();

        long now =
                System.currentTimeMillis();

        Set<String> allKnownPlayers =
                new HashSet<>();

        allKnownPlayers.addAll(
                displayNames.keySet()
        );

        allKnownPlayers.addAll(
                lastSeenAtCorp.keySet()
        );

        allKnownPlayers.addAll(
                customers.keySet()
        );

        for (String normalizedName :
                allKnownPlayers)
        {
            if (normalizedName == null ||
                    normalizedName.isEmpty())
            {
                continue;
            }

            if (isHidden(normalizedName))
            {
                continue;
            }

            String displayName =
                    displayNames.getOrDefault(
                            normalizedName,
                            normalizedName
                    );

            String cleanDisplayName =
                    removeYouSuffix(
                            displayName
                    );

            long lastSeen =
                    lastSeenAtCorp.getOrDefault(
                            normalizedName,
                            0L
                    );

            long awayDuration =
                    lastSeen <= 0
                            ? Long.MAX_VALUE
                            : now - lastSeen;

            boolean currentlyVisible =
                    isCurrentlyVisible(
                            normalizedName
                    );

            boolean isTemporarilyAway =
                    !currentlyVisible &&
                            lastSeen > 0 &&
                            awayDuration <
                                    AWAY_GRACE_PERIOD_MS;

            boolean isAway =
                    !currentlyVisible &&
                            lastSeen > 0 &&
                            awayDuration >=
                                    AWAY_GRACE_PERIOD_MS;

            boolean isCustomer =
                    customers.containsKey(
                            normalizedName
                    );

            boolean isLowHp =
                    currentLowHpPlayers.contains(
                            normalizedName
                    );

            int playerKills =
                    getPlayerKillCount(
                            normalizedName
                    );

            String specText =
                    getLastSpecText(
                            normalizedName
                    );

            PlayerRowData rowData =
                    new PlayerRowData(
                            normalizedName,
                            cleanDisplayName,
                            specText,
                            playerKills,
                            isLowHp,
                            isTemporarilyAway,
                            isAway,
                            lastSeen
                    );

            if (isCustomer &&
                    awayDuration < CUSTOMER_AWAY_AFTER_MS)
            {
                customerPlayers.add(rowData);
            }
            else if (isAway)
            {
                awayPlayers.add(rowData);
            }
            else
            {
                activePlayers.add(rowData);
            }
        }

        activePlayers.sort(
                Comparator
                        .comparing(
                                (PlayerRowData row) ->
                                        !row.lowHp
                        )
                        .thenComparing(
                                row ->
                                        row.displayName
                                                .toLowerCase()
                        )
        );

        customerPlayers.sort(
                Comparator.comparing(
                        row ->
                                row.displayName
                                        .toLowerCase()
                )
        );

        awayPlayers.sort(
                Comparator
                        .comparingLong(
                                (PlayerRowData row) ->
                                        row.lastSeen
                        )
                        .reversed()
        );

        addCategory(
                "Active Players",
                activePlayers,
                PlayerCategory.ACTIVE
        );

        addCategory(
                "Clients",
                customerPlayers,
                PlayerCategory.CUSTOMER
        );

        addCategory(
                "Away / AFK",
                awayPlayers,
                PlayerCategory.AWAY
        );

        updateHiddenButtonText();

        playerListPanel.revalidate();
        playerListPanel.repaint();

        playerScrollPane
                .getViewport()
                .revalidate();

        playerScrollPane
                .getViewport()
                .repaint();

        /*
         * Restore the previous position after Swing recalculates
         * the new scrollbar range.
         */
        SwingUtilities.invokeLater(() ->
        {
            int maximumValue =
                    Math.max(
                            verticalBar.getMinimum(),
                            verticalBar.getMaximum() -
                                    verticalBar.getVisibleAmount()
                    );

            verticalBar.setValue(
                    Math.max(
                            verticalBar.getMinimum(),
                            Math.min(
                                    previousScrollValue,
                                    maximumValue
                            )
                    )
            );
        });
    }

    private void addCategory(
            String title,
            List<PlayerRowData> players,
            PlayerCategory category)
    {
        boolean collapsed =
                isCategoryCollapsed(category);

        JPanel headerPanel =
                new JPanel(
                        new BorderLayout()
                );

        headerPanel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        headerPanel.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(
                                0,
                                0,
                                1,
                                0,
                                ColorScheme.MEDIUM_GRAY_COLOR
                        ),
                        BorderFactory.createEmptyBorder(
                                6,
                                7,
                                6,
                                7
                        )
                )
        );

        headerPanel.setMaximumSize(
                new Dimension(
                        Integer.MAX_VALUE,
                        32
                )
        );

        /*
         * Show a down arrow when expanded and a right arrow
         * when collapsed.
         */
        String arrow =
                collapsed
                        ? "▶ "
                        : "▼ ";

        JLabel categoryLabel =
                new JLabel(
                        arrow +
                                title.toUpperCase() +
                                "  (" +
                                players.size() +
                                ")"
                );

        categoryLabel.setForeground(
                getCategoryColor(category)
        );

        categoryLabel.setFont(
                categoryLabel
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                11f
                        )
        );

        headerPanel.add(
                categoryLabel,
                BorderLayout.WEST
        );

        /*
         * Hand cursor shows users that the header is clickable.
         */
        headerPanel.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR
                )
        );

        categoryLabel.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR
                )
        );

        /*
         * Clicking either the header background or its text
         * collapses/expands the category.
         */
        MouseAdapter collapseListener =
                new MouseAdapter()
                {
                    @Override
                    public void mouseClicked(
                            MouseEvent event)
                    {
                        if (!SwingUtilities.isLeftMouseButton(event))
                        {
                            return;
                        }

                        toggleCategoryCollapsed(
                                category
                        );
                    }
                };

        headerPanel.addMouseListener(
                collapseListener
        );

        categoryLabel.addMouseListener(
                collapseListener
        );

        /*
         * Mouse-wheel scrolling still works over the header.
         */
        enablePlayerListScrolling(
                headerPanel
        );

        playerListPanel.add(
                headerPanel
        );

        playerListPanel.add(
                Box.createVerticalStrut(3)
        );

        /*
         * Stop here when the category is collapsed.
         * The header remains visible, but its player rows are hidden.
         */
        if (collapsed)
        {
            playerListPanel.add(
                    Box.createVerticalStrut(5)
            );

            return;
        }

        if (players.isEmpty())
        {
            JLabel emptyLabel =
                    new JLabel(
                            "No players"
                    );

            emptyLabel.setForeground(
                    SECONDARY_TEXT_COLOR
            );

            emptyLabel.setBorder(
                    BorderFactory.createEmptyBorder(
                            5,
                            10,
                            7,
                            2
                    )
            );

            enablePlayerListScrolling(
                    emptyLabel
            );

            playerListPanel.add(
                    emptyLabel
            );
        }
        else
        {
            for (PlayerRowData player : players)
            {
                playerListPanel.add(
                        createPlayerRow(
                                player,
                                category
                        )
                );

                playerListPanel.add(
                        Box.createVerticalStrut(2)
                );
            }
        }

        playerListPanel.add(
                Box.createVerticalStrut(8)
        );
    }

    private boolean isCategoryCollapsed(
            PlayerCategory category)
    {
        switch (category)
        {
            case CUSTOMER:
                return customersCollapsed;

            case AWAY:
                return awayPlayersCollapsed;

            case ACTIVE:
            default:
                return activePlayersCollapsed;
        }
    }

    private void toggleCategoryCollapsed(
            PlayerCategory category)
    {
        switch (category)
        {
            case CUSTOMER:
                customersCollapsed =
                        !customersCollapsed;
                break;

            case AWAY:
                awayPlayersCollapsed =
                        !awayPlayersCollapsed;
                break;

            case ACTIVE:
            default:
                activePlayersCollapsed =
                        !activePlayersCollapsed;
                break;
        }

        refreshPlayerDisplay();
    }

    private JPanel createPlayerRow(
