    private void installPlayerMenu(
            Component component,
            String normalizedName)
    {
        component.addMouseListener(
                new MouseAdapter()
                {
                    @Override
                    public void mousePressed(
                            MouseEvent event)
                    {
                        showPopupIfRequired(
                                event
                        );
                    }

                    @Override
                    public void mouseReleased(
                            MouseEvent event)
                    {
                        showPopupIfRequired(
                                event
                        );
                    }

                    private void showPopupIfRequired(
                            MouseEvent event)
                    {
                        if (!event.isPopupTrigger())
                        {
                            return;
                        }

                        JPopupMenu menu =
                                createPlayerPopupMenu(
                                        normalizedName
                                );

                        menu.show(
                                event.getComponent(),
                                event.getX(),
                                event.getY()
                        );
                    }
                }
        );
    }
    public void setPackageCompleteCallback(
            Consumer<String> packageCompleteCallback)
    {
        this.packageCompleteCallback =
                packageCompleteCallback;
    }
