    private void addPlayerKill(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        if (giveKillCallback != null)
        {
            giveKillCallback.accept(
                    displayName
            );

            return;
        }

        String matchingKey =
                findKillCountKey(
                        normalizedName
                );

        killCountReference.put(
                matchingKey,
                killCountReference.getOrDefault(
                        matchingKey,
                        0
                ) + 1
        );

        refreshPlayerDisplay();
    }
    private void resetCustomerPackage(String normalizedName)
    {
        CustomerPackage customerPackage =
                customers.get(normalizedName);

        if (customerPackage == null)
        {
            return;
        }

        customerPackage.packageKills = 0;
        customerPackage.completed = false;

        refreshPlayerDisplay();
    }
    private void removePlayerKill(
            String normalizedName)
    {
        String key =
                findKillCountKey(
                        normalizedName
                );

        int currentKills =
                killCountReference.getOrDefault(
                        key,
                        0
                );

        if (currentKills <= 1)
        {
            killCountReference.remove(
                    key
            );
        }
        else
        {
            killCountReference.put(
                    key,
                    currentKills - 1
            );
        }

        refreshPlayerDisplay();
    }

    private void resetPlayerKillCount(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        int result =
                JOptionPane.showConfirmDialog(
                        this,
                        "Reset KC for " +
                                displayName +
                                "?",
                        "Reset Player KC",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.WARNING_MESSAGE
                );

        if (result !=
                JOptionPane.YES_OPTION)
        {
            return;
        }

        String key =
                findKillCountKey(
                        normalizedName
                );

        killCountReference.remove(
                key
        );

        refreshPlayerDisplay();
    }

    private void setCustomer(
            String normalizedName)
    {
        customers.computeIfAbsent(
                normalizedName,
                name ->
                        new CustomerPackage()
        );

        refreshPlayerDisplay();
    }

    private void removeCustomer(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        int result =
                JOptionPane.showConfirmDialog(
                        this,
                        "Remove " +
                                displayName +
                                " as a client?",
                        "Remove Client",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.QUESTION_MESSAGE
                );

        if (result !=
                JOptionPane.YES_OPTION)
        {
            return;
        }

        customers.remove(
                normalizedName
        );

        refreshPlayerDisplay();
    }

    private void setCustomerPackageSize(
            String normalizedName)
    {
        setCustomer(
                normalizedName
        );

        CustomerPackage customerPackage =
                customers.get(
                        normalizedName
                );

        String existingValue =
                customerPackage.packageSize > 0
                        ? String.valueOf(
                        customerPackage.packageSize
                )
                        : "";

        String input =
                JOptionPane.showInputDialog(
                        this,
                        "Enter package size for " +
                                getDisplayName(
                                        normalizedName
                                ) +
                                ":",
                        existingValue
                );

        if (input == null)
        {
            return;
        }

        input =
                input.trim();

        if (input.isEmpty())
        {
            return;
        }

        try
        {
            int packageSize =
                    Integer.parseInt(
                            input
                    );

            if (packageSize <= 0)
            {
                throw new NumberFormatException();
            }

            customerPackage.packageSize =
                    packageSize;

            customerPackage.completed =
                    customerPackage.packageKills >=
                            packageSize;

            refreshPlayerDisplay();
        }
        catch (NumberFormatException exception)
        {
            JOptionPane.showMessageDialog(
                    this,
                    "Package size must be a number greater than 0.",
                    "Invalid Package Size",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

    private void addCustomerPackageKill(
            String normalizedName)
    {
        setCustomer(normalizedName);

        CustomerPackage customerPackage =
                customers.get(normalizedName);

        /*
         * Remember whether it was already complete so the
         * chat message is sent only once.
         */
        boolean wasAlreadyCompleted =
                customerPackage.completed;

        customerPackage.packageKills++;

        if (customerPackage.packageSize > 0 &&
                customerPackage.packageKills >=
                        customerPackage.packageSize)
        {
            customerPackage.packageKills =
                    customerPackage.packageSize;

            customerPackage.completed = true;

            if (!wasAlreadyCompleted &&
                    packageCompleteCallback != null)
            {
                String playerName =
                        getDisplayName(normalizedName);

                packageCompleteCallback.accept(
                        "\"[WeCorp] Package Complete! \" " +
                                playerName +
                                " has finished their " +
                                customerPackage.packageSize +
                                "/" +
                                customerPackage.packageSize +
                                " KC package."
                );
            }
        }

        refreshPlayerDisplay();
    }

    private void markCustomerPackageComplete(
            String normalizedName)
    {
        setCustomer(
                normalizedName
        );

        CustomerPackage customerPackage =
                customers.get(
                        normalizedName
                );

        if (customerPackage.packageSize > 0)
        {
            customerPackage.packageKills =
                    customerPackage.packageSize;
        }

        customerPackage.completed =
                true;

        refreshPlayerDisplay();
    }

    private void hidePlayer(
            String normalizedName)
    {
        hiddenPlayersReference.add(
                normalizedName
        );

        refreshPlayerDisplay();
    }

    private void unhidePlayer(
            String normalizedName)
    {
        removeNormalizedName(
                hiddenPlayersReference,
                normalizedName
        );

        refreshPlayerDisplay();
    }

    private void showHiddenPlayersMenu()
    {
        JPopupMenu hiddenMenu =
                new JPopupMenu();

        List<String> hiddenNames =
                getNormalizedHiddenPlayers();

        if (hiddenNames.isEmpty())
        {
            JMenuItem emptyItem =
                    new JMenuItem(
                            "No hidden players"
                    );

            emptyItem.setEnabled(false);

            hiddenMenu.add(
                    emptyItem
            );
        }
        else
        {
            hiddenNames.sort(
                    Comparator.comparing(
                            this::getDisplayName
                    )
            );

            for (String normalizedName :
                    hiddenNames)
            {
                JMenuItem playerItem =
                        new JMenuItem(
                                "Unhide " +
                                        getDisplayName(
                                                normalizedName
                                        )
                        );

                playerItem.addActionListener(
                        event ->
                                unhidePlayer(
                                        normalizedName
                                )
                );

                hiddenMenu.add(
                        playerItem
                );
            }

            hiddenMenu.addSeparator();

            JMenuItem unhideAllItem =
                    new JMenuItem(
                            "Unhide All"
                    );

            unhideAllItem.addActionListener(
                    event ->
                    {
                        hiddenPlayersReference.clear();

                        refreshPlayerDisplay();
                    }
            );

            hiddenMenu.add(
                    unhideAllItem
            );
        }

        hiddenMenu.show(
                showHiddenButton,
                0,
                showHiddenButton.getHeight()
        );
    }

    private void copyPlayerName(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        try
        {
            StringSelection selection =
                    new StringSelection(
                            displayName
                    );

            Toolkit
                    .getDefaultToolkit()
                    .getSystemClipboard()
                    .setContents(
                            selection,
                            selection
                    );
        }
        catch (IllegalStateException exception)
        {
            JOptionPane.showMessageDialog(
                    this,
                    "Could not copy the player name.",
                    "Copy Failed",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

    private void confirmFullReset()
    {
        int result =
                JOptionPane.showConfirmDialog(
                        this,
                        "Reset the full WeCorpCC trip?\n" +
                                "This clears KC, clients, packages and hidden players.",
                        "Reset Trip",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.WARNING_MESSAGE
                );

        if (result ==
                JOptionPane.YES_OPTION &&
                resetCallback != null)
        {
            resetCallback.run();
        }
    }
    public void resetPanel()
    {
        SwingUtilities.invokeLater(() ->
        {
            currentPlayerInfo.clear();
            lastPlayerInfo.clear();
            currentLowHpPlayers.clear();
            currentLastKillAttendees.clear();

            displayNames.clear();
            lastSeenAtCorp.clear();
            customers.clear();

            killCountReference =
                    new HashMap<>();

            hiddenPlayersReference =
                    new HashSet<>();

            setCompactStatus(
                    "Waiting for Corp...",
                    "0",
                    "0",
                    "0m 0s",
                    "0s",
                    "0"
            );

            statusLabel.setText("");
            statusLabel.setVisible(false);

            refreshPlayerDisplay();
        });
    }

    private boolean isCurrentlyVisible(
            String normalizedName)
    {
        for (String displayName :
                currentPlayerInfo.keySet())
        {
            if (normalizeName(displayName)
                    .equals(normalizedName))
            {
                return true;
            }
        }

        return false;
    }

    private boolean isHidden(
            String normalizedName)
    {
        for (String hiddenName :
                hiddenPlayersReference)
        {
            if (normalizeName(hiddenName)
                    .equals(normalizedName))
            {
                return true;
            }
        }

        return false;
    }

    private List<String> getNormalizedHiddenPlayers()
    {
        Set<String> normalizedNames =
                new HashSet<>();

        for (String hiddenName :
                hiddenPlayersReference)
        {
            String normalizedName =
                    normalizeName(hiddenName);

            if (!normalizedName.isEmpty())
            {
                normalizedNames.add(
                        normalizedName
                );
            }
        }

        return new ArrayList<>(
                normalizedNames
        );
    }

    private void removeNormalizedName(
            Set<String> names,
            String normalizedName)
    {
        names.removeIf(
                name ->
                        normalizeName(name)
                                .equals(normalizedName)
        );
    }

    private int getPlayerKillCount(
            String normalizedName)
    {
        for (Map.Entry<String, Integer> entry :
                killCountReference.entrySet())
        {
            if (normalizeName(entry.getKey())
                    .equals(normalizedName))
            {
                return entry.getValue() == null
                        ? 0
                        : entry.getValue();
            }
        }

        return 0;
    }

    private String findKillCountKey(
            String normalizedName)
    {
        for (String key :
                killCountReference.keySet())
        {
            if (normalizeName(key)
                    .equals(normalizedName))
            {
                return key;
            }
        }

        return getDisplayName(
                normalizedName
        );
    }

    private String getLastSpecText(
            String normalizedName)
    {
        return lastPlayerInfo.getOrDefault(
                normalizedName,
                ""
        );
    }

    private String getDisplayName(
            String normalizedName)
    {
        String displayName =
                displayNames.getOrDefault(
                        normalizedName,
                        normalizedName
                );

        return removeYouSuffix(
                displayName
        );
    }

    private String normalizeName(
            String name)
    {
        if (name == null)
        {
            return "";
        }

        return removeYouSuffix(name)
                .replace('\u00A0', ' ')
                .replaceAll("\\s+", " ")
                .trim()
                .toLowerCase();
    }

    private String removeYouSuffix(
            String name)
    {
        if (name == null)
        {
            return "";
        }

        return name
                .replace('\u00A0', ' ')
                .replace(" (You)", "")
                .replaceAll("\\s+", " ")
                .trim();
    }

    private String formatAfkTime(
            long milliseconds)
    {
        if (milliseconds < 0 ||
                milliseconds == Long.MAX_VALUE)
        {
            return "unknown";
        }

        long totalSeconds =
                milliseconds / 1000;

        long minutes =
                totalSeconds / 60;

        long seconds =
                totalSeconds % 60;

        if (minutes <= 0)
        {
            return seconds + "s";
        }

        if (seconds == 0)
        {
            return minutes == 1
                    ? "1 min"
                    : minutes + " mins";
        }

        return minutes +
                "m " +
                seconds +
                "s";
    }

    private void updateHiddenButtonText()
    {
        int hiddenCount =
                getNormalizedHiddenPlayers()
                        .size();

        showHiddenButton.setText(
                hiddenCount > 0
                        ? "Hidden Players (" +
                        hiddenCount +
                        ")"
                        : "Hidden Players"
        );
    }

    private enum PlayerCategory
    {
        ACTIVE,
        CUSTOMER,
        AWAY
    }

    private static class CustomerPackage
    {
        private int packageSize;
        private int packageKills;
        private boolean completed;
    }

    private static class PlayerRowData
    {
        private final String normalizedName;
        private final String displayName;
        private final String specText;
        private final int kills;
        private final boolean lowHp;
        private final boolean temporarilyAway;
        private final boolean away;
        private final long lastSeen;

        private PlayerRowData(
                String normalizedName,
                String displayName,
                String specText,
                int kills,
                boolean lowHp,
                boolean temporarilyAway,
                boolean away,
                long lastSeen)
        {
            this.normalizedName =
                    normalizedName;

            this.displayName =
                    displayName;

            this.specText =
                    specText;

            this.kills =
                    kills;

            this.lowHp =
                    lowHp;

            this.temporarilyAway =
                    temporarilyAway;

            this.away =
                    away;

            this.lastSeen =
                    lastSeen;
        }
    }
