    private JPanel createCollapsibleSection(
            String title,
            JPanel contentPanel,
            SectionType sectionType)
    {
        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        wrapper.setAlignmentX(Component.CENTER_ALIGNMENT);

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
                BorderFactory.createEmptyBorder(6, 7, 6, 7)
        ));
        header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));

        JLabel headerLabel = new JLabel();
        headerLabel.setForeground(SECONDARY_TEXT_COLOR);
        headerLabel.setFont(headerLabel.getFont().deriveFont(Font.BOLD, 11f));
        header.add(headerLabel, BorderLayout.WEST);

        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        headerLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        Runnable refreshSection = () ->
        {
            boolean collapsed = isTopSectionCollapsed(sectionType);
            headerLabel.setText((collapsed ? "▶ " : "▼ ") + title);
            contentPanel.setVisible(!collapsed);
            wrapper.revalidate();
            wrapper.repaint();
        };

        MouseAdapter listener = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent event)
            {
                if (!SwingUtilities.isLeftMouseButton(event))
                {
                    return;
                }

                toggleTopSection(sectionType);
                refreshSection.run();
            }
        };

        header.addMouseListener(listener);
        headerLabel.addMouseListener(listener);

        wrapper.add(header);
        wrapper.add(Box.createVerticalStrut(3));
        wrapper.add(contentPanel);

        refreshSection.run();
        return wrapper;
    }

    private boolean isTopSectionCollapsed(SectionType sectionType)
    {
        switch (sectionType)
        {
            case OVERVIEW:
                return overviewCollapsed;
            case CURRENT_KILL:
                return currentKillCollapsed;
            case DROPS:
            default:
                return dropsCollapsed;
        }
    }

    private void toggleTopSection(SectionType sectionType)
    {
        switch (sectionType)
        {
            case OVERVIEW:
                overviewCollapsed = !overviewCollapsed;
                break;
            case CURRENT_KILL:
                currentKillCollapsed = !currentKillCollapsed;
                break;
            case DROPS:
            default:
                dropsCollapsed = !dropsCollapsed;
                break;
        }
    }

    private void addStatRow(
            JPanel panel,
            int row,
            String text,
            Color color,
            JLabel valueLabel)
    {
        JLabel dot = new JLabel("●");
        dot.setForeground(color);
        dot.setFont(dot.getFont().deriveFont(Font.BOLD, 13f));

        JLabel name = new JLabel(text);
        name.setForeground(SECONDARY_TEXT_COLOR);
        name.setFont(name.getFont().deriveFont(Font.PLAIN, 12f));

        valueLabel.setForeground(Color.WHITE);
        valueLabel.setFont(
                valueLabel.getFont().deriveFont(Font.BOLD, 12f)
        );
        valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);

        GridBagConstraints c0 = new GridBagConstraints();
        c0.gridx = 0;
        c0.gridy = row;
        c0.anchor = GridBagConstraints.WEST;
        c0.insets = new Insets(1, 0, 1, 5);
        panel.add(dot, c0);

        GridBagConstraints c1 = new GridBagConstraints();
        c1.gridx = 1;
        c1.gridy = row;
        c1.weightx = 1.0;
        c1.fill = GridBagConstraints.HORIZONTAL;
        c1.anchor = GridBagConstraints.WEST;
        c1.insets = new Insets(1, 0, 1, 5);
        panel.add(name, c1);

        GridBagConstraints c2 = new GridBagConstraints();
        c2.gridx = 2;
        c2.gridy = row;
        c2.anchor = GridBagConstraints.EAST;
        c2.insets = new Insets(1, 5, 1, 0);
        panel.add(valueLabel, c2);
    }

    private void enablePlayerListScrolling(
            Component component)
    {
        /*
         * Forward wheel movement from the Mass player-list area to
         * RuneLite's OUTER plugin-panel scrollbar.
         *
         * This changes only mouse-wheel behavior.  The Mass design,
         * colors, counters, rows, KC and drop/spec logic stay untouched.
         */
        if (component instanceof javax.swing.JComponent)
        {
            javax.swing.JComponent swingComponent =
                    (javax.swing.JComponent) component;

            if (Boolean.TRUE.equals(
                    swingComponent.getClientProperty(
                            "wecorpcc.massOuterScrollInstalled"
                    )))
            {
                return;
            }

            swingComponent.putClientProperty(
                    "wecorpcc.massOuterScrollInstalled",
                    Boolean.TRUE
            );
        }

        component.addMouseWheelListener(
                event ->
                {
                    javax.swing.JScrollPane outerScrollPane =
                            findOuterScrollPane();

                    javax.swing.JScrollBar scrollBar =
                            outerScrollPane != null
                                    ? outerScrollPane.getVerticalScrollBar()
                                    : playerScrollPane.getVerticalScrollBar();

                    if (scrollBar == null)
                    {
                        return;
                    }

                    int direction =
                            event.getWheelRotation();

                    if (direction == 0)
                    {
                        return;
                    }

                    int increment =
                            Math.max(
                                    18,
                                    scrollBar.getUnitIncrement(direction)
                            );

                    int maximumValue =
                            Math.max(
                                    scrollBar.getMinimum(),
                                    scrollBar.getMaximum() -
                                            scrollBar.getVisibleAmount()
                            );

                    int newValue =
                            scrollBar.getValue() +
                                    (direction * increment * 3);

                    scrollBar.setValue(
                            Math.max(
                                    scrollBar.getMinimum(),
                                    Math.min(
                                            newValue,
                                            maximumValue
                                    )
                            )
                    );

                    event.consume();
                }
        );

        if (component instanceof Container)
        {
            Container container =
                    (Container) component;

            for (Component child :
                    container.getComponents())
            {
                enablePlayerListScrolling(child);
            }
        }
    }

    private javax.swing.JScrollPane findOuterScrollPane()
    {
        java.awt.Container parent =
                playerScrollPane.getParent();

        while (parent != null)
        {
            if (parent instanceof javax.swing.JScrollPane)
            {
                return (javax.swing.JScrollPane) parent;
            }

            parent = parent.getParent();
        }

        return null;
    }

