        GridBagConstraints valueConstraints =
                new GridBagConstraints();

        valueConstraints.gridx = 1;
        valueConstraints.gridy = row * 2;
        valueConstraints.anchor =
                GridBagConstraints.EAST;

        valueConstraints.insets =
                new Insets(
                        row == 0 ? 0 : 8,
                        5,
                        3,
