    public void setDwhCount(int count)
    {
        startPreparationIfNeeded();

        dwhCount = Math.max(
                0,
                count
        );

        refreshDisplay();
    }

    public void setBgsDamage(int damage)
    {
        startPreparationIfNeeded();

        bgsDamage = Math.max(
                0,
                damage
        );

        refreshDisplay();
    }

    public void setArclightCount(int count)
    {
        startPreparationIfNeeded();

        arclightCount = Math.max(
                0,
                count
        );

        refreshDisplay();
    }

    public void addDwhSpec()
    {
        setDwhCount(
                dwhCount + 1
        );
    }

    public void addBgsDamage(int damage)
    {
        setBgsDamage(
                bgsDamage +
                        Math.max(0, damage)
        );
    }

    public void addArclightHit()
    {
        setArclightCount(
                arclightCount + 1
        );
    }

    public void resetProgress()
    {
        dwhCount = 0;
        bgsDamage = 0;
        arclightCount = 0;

        preparationStarted = false;
        prepStartTime = 0;

        refreshDisplay();
        refreshTimer();
        readyMessageSent = false;
    }

    private void startPreparationIfNeeded()
    {
        if (preparationStarted)
        {
            return;
        }

        preparationStarted = true;
        prepStartTime =
                System.currentTimeMillis();
    }

    private void refreshDisplay()
    {
        SwingUtilities.invokeLater(() ->
        {
            boolean method2 = isMethod2();
            int bgsTarget = method2 ? METHOD_2_BGS_TARGET : BGS_TARGET;

            if (dwhRowPanel != null)
            {
                dwhRowPanel.setVisible(!method2);
            }

            if (arclightRowPanel != null)
            {
                arclightRowPanel.setVisible(!method2);
            }

            if (bgsRowPanel != null)
            {
                bgsRowPanel.setVisible(true);
            }

            int shownDwh = Math.min(dwhCount, DWH_TARGET);
            int shownBgs = Math.min(bgsDamage, bgsTarget);
            int shownArclight = Math.min(arclightCount, ARCLIGHT_TARGET);

            dwhProgress.setMaximum(DWH_TARGET);
            arclightProgress.setMaximum(ARCLIGHT_TARGET);
            bgsProgress.setMaximum(bgsTarget);

            dwhProgress.setValue(shownDwh);
            bgsProgress.setValue(shownBgs);
            arclightProgress.setValue(shownArclight);

            dwhValueLabel.setText(
                    method2 ? "Not required" : shownDwh + " / " + DWH_TARGET
            );

            arclightValueLabel.setText(
                    method2 ? "Not required" : shownArclight + " / " + ARCLIGHT_TARGET
            );

            bgsValueLabel.setText(
                    shownBgs + " / " + bgsTarget
            );

            updateProgressColor(
                    dwhProgress,
                    method2 || shownDwh >= DWH_TARGET
            );

            updateProgressColor(
                    arclightProgress,
                    method2 || shownArclight >= ARCLIGHT_TARGET
            );

            updateProgressColor(
                    bgsProgress,
                    shownBgs >= bgsTarget
            );

            boolean ready = method2
                    ? bgsDamage >= METHOD_2_BGS_TARGET
                    : dwhCount >= DWH_TARGET &&
                            arclightCount >= ARCLIGHT_TARGET &&
                            bgsDamage >= BGS_TARGET;

            if (ready && !readyMessageSent)
            {
                readyMessageSent = true;

                if (readyCallback != null)
                {
                    readyCallback.run();
                }
            }

            if (!ready)
            {
                readyMessageSent = false;
            }

            statusLabel.setText(
                    ready
                            ? "READY TO KILL"
                            : "PREPARING"
            );

            statusLabel.setForeground(
                    ready
                            ? COMPLETE_COLOR
                            : INCOMPLETE_COLOR
            );

            updateRemainingText();

            revalidate();
            repaint();
        });
    }

    private void updateRemainingText()
    {
        boolean method2 = isMethod2();

        boolean ready = method2
                ? bgsDamage >= METHOD_2_BGS_TARGET
                : dwhCount >= DWH_TARGET &&
                        arclightCount >= ARCLIGHT_TARGET &&
                        bgsDamage >= BGS_TARGET;

        if (ready)
        {
            remainingLabel.setText(
                    "<html><center>" +
                            "<font color='#32CD32'><b>" +
                            "All defence reductions complete." +
                            "</b></font>" +
                            "</center></html>"
            );
            return;
        }

        StringBuilder text =
                new StringBuilder("<html><center>");

        if (method2)
        {
            int remainingBgs =
                    Math.max(0, METHOD_2_BGS_TARGET - bgsDamage);

            text.append("Need ")
                    .append(remainingBgs)
                    .append(" BGS damage");
        }
        else
        {
            int remainingDwh =
                    Math.max(0, DWH_TARGET - dwhCount);

            int remainingArclight =
                    Math.max(0, ARCLIGHT_TARGET - arclightCount);

            int remainingBgs =
                    Math.max(0, BGS_TARGET - bgsDamage);

            if (remainingDwh > 0)
            {
                text.append("Need ")
                        .append(remainingDwh)
                        .append(" more DWH / Maul<br>");
            }

            if (remainingArclight > 0)
            {
                text.append("Need ")
                        .append(remainingArclight)
                        .append(" more Arclight / Emberlight<br>");
            }

            if (remainingBgs > 0)
            {
                text.append("Need ")
                        .append(remainingBgs)
                        .append(" BGS damage<br>");
            }
        }

        text.append("</center></html>");
        remainingLabel.setText(text.toString());
    }

    private void updateProgressColor(
            JProgressBar progressBar,
            boolean complete)
    {
        progressBar.setForeground(
                complete
                        ? COMPLETE_COLOR
                        : INCOMPLETE_COLOR
        );
    }

    private void refreshTimer()
    {
        if (!preparationStarted ||
                prepStartTime <= 0)
        {
            prepTimeLabel.setText(
                    "0m 00s"
            );

            return;
        }

        long totalSeconds =
                (System.currentTimeMillis() -
                        prepStartTime) / 1000;

        long minutes =
                totalSeconds / 60;

        long seconds =
                totalSeconds % 60;

        prepTimeLabel.setText(
                String.format(
                        "%dm %02ds",
                        minutes,
                        seconds
                )
        );
    }
    private void showSoloGuide()
    {
        String guide =
                "WeCorpCC Solo Guide\n\n" +
                        "Method 1\n" +
                        "- 4 successful DWH / Maul specs\n" +
                        "- 20 successful Arclight / Emberlight specs\n" +
                        "- 200 total BGS spec damage\n\n" +

                        "Method 2\n" +
                        "- 500 total BGS spec damage\n\n" +

                        "Zero damage doesn't count.\n" +
                        "Normal Arclight / Emberlight attacks don't count.\n\n" +

                        "READY TO KILL when the selected method is complete.";

        JOptionPane.showMessageDialog(
                this,
                guide,
                "Solo Guide",
                JOptionPane.INFORMATION_MESSAGE
        );
    }
}

