    private void fullReset() {
        clearPendingSoloSpec();
        clearPendingMassBgs();
        firstKillTime = 0;
        if (totalKills > 0 || tripStartTime > 0) {
            long tripSeconds = tripStartTime > 0
                    ? (System.currentTimeMillis() - tripStartTime) / 1000
                    : 0;

            long minutes = tripSeconds / 60;
            long seconds = tripSeconds % 60;

            String kphValue = calculateKph();

            final String summaryTitle =
                    "<col=0066CC>WeCorpCC Session Summary</col>";

            final String summaryDetails =
                    "Kills: " + totalKills +
                            " | KPH: " + kphValue +
                            " | Time: " +
                            minutes + "m " + seconds + "s";

            clientThread.invoke(() ->
            {
                client.addChatMessage(
                        ChatMessageType.GAMEMESSAGE,
                        "",
                        summaryTitle,
                        null
                );

                client.addChatMessage(
                        ChatMessageType.GAMEMESSAGE,
                        "",
                        summaryDetails,
                        null
                );
            });
        }

        clearData();

        killCount.clear();
        lastKillAttendees.clear();
        lowHpWarned.clear();
        lowHpPlayers.clear();
        currentKillAttendees.clear();
        customers.clear();
        hiddenPlayers.clear();
        lastSeenAtCorp.clear();

        totalKills = 0;
        tripStartTime = 0;
        killStartTime = 0;
        corpDeathTime = 0;
        corpAlive = false;
        corpKillProcessed = false;
        atCorp = false;
        lastAnnouncedTarget = 0;
        lastAtCorpTime = 0;
        notAtCorpTicks = 0;
        tickCounter = 0;
        lastDropMessage = "";
        lastDropTime = 0;

        panel.resetPanel();
        updateWaitingStatus();
