    private void checkLowHp(Player player, String name) {
        String normalizedName = normalizeName(name);

        if (!config.lowHpWarning()) {
            lowHpPlayers.remove(normalizedName);
            lowHpWarned.remove(normalizedName);
            return;
        }

        String configuredNames = config.lowHpNames();

        String watchList =
                configuredNames == null
                        ? ""
                        : configuredNames.trim();

        if (!watchList.isEmpty()) {
            boolean inList = false;

            for (String watchedName : watchList.split(",")) {
                if (watchedName.trim().equalsIgnoreCase(name)) {
                    inList = true;
                    break;
                }
            }

            if (!inList) {
                lowHpPlayers.remove(normalizedName);
                lowHpWarned.remove(normalizedName);
                return;
            }
        }

        int healthRatio = player.getHealthRatio();
        int healthScale = player.getHealthScale();

        if (healthScale <= 0 || healthRatio < 0) {
            return;
        }

        double percentage =
                (double) healthRatio / healthScale * 100.0;

        if (percentage <= 40.0) {
            lowHpPlayers.add(normalizedName);

            if (!lowHpWarned.contains(normalizedName)) {
                client.addChatMessage(
                        ChatMessageType.GAMEMESSAGE,
                        "",
                        name + " is low HP!",
                        null
                );

                lowHpWarned.add(normalizedName);
            }
        } else {
            lowHpPlayers.remove(normalizedName);
            lowHpWarned.remove(normalizedName);
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarpId() != 300) {
            return;
        }

        int currentSpecialEnergy =
                client.getVarpValue(300);

        if (lastSpecialEnergy < 0) {
            lastSpecialEnergy = currentSpecialEnergy;
            return;
        }

        boolean specialEnergyDropped =
                currentSpecialEnergy < lastSpecialEnergy;

        lastSpecialEnergy = currentSpecialEnergy;

        if (!specialEnergyDropped) {
            return;
        }

        if (!atCorp) {
            return;
        }

        /*
         * Existing Solo Arclight handling.
         *
         * Elder Maul is no longer handled here.
         * Elder Maul is detected in onAnimationChanged()
         * so remote players can also be tracked.
         */
        if (config.pluginMode() != PluginMode.SOLO ||
                soloPanel == null ||
                !isArclightEquipped()) {
            return;
        }

        pendingSoloArclight = true;
        pendingSoloDwh = false;
        pendingSoloBgs = false;
        pendingSoloMaul = false;

        pendingSoloSpecGameCycle =
                client.getGameCycle();
    }

    int getOverlayDwhCount()
    {
        int total = 0;

        for (int count : dwhCount.values())
        {
            total += count;
        }

        return total;
    }
    boolean isOverlayCustomer(String playerName)
    {
        return panel != null &&
                panel.isCustomer(playerName);
    }

    int getOverlayMaulCount()
    {
        int total = 0;

        for (int count : maulCount.values())
        {
            total += count;
        }

        return total;
    }

    int getLocalCorpDamage()
    {
        return localCorpDamage;
    }

    @Provides
    WeCorpConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(WeCorpConfig.class);
    }
}

package com.wecorpcc;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.awt.Font;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.plugins.specialcounter.SpecialCounterUpdate;

public class ModePanel extends PluginPanel
{
    private static final String BOOSTING_CARD = "BOOSTING";
    private static final String SOLO_CARD = "SOLO";
    private static final String MASS_CARD = "MASS";

    private static final Color ACTIVE_COLOR =
            new Color(50, 205, 50);

    private static final Color INACTIVE_COLOR =
            new Color(180, 180, 180);

    private final CardLayout cardLayout =
            new CardLayout();

    private final JPanel cardPanel =
            new JPanel(cardLayout);

    private final Map<PluginMode, JButton> modeButtons =
            new EnumMap<>(PluginMode.class);

    private final Consumer<PluginMode> modeChangedCallback;
    private final WeCorpOverlay weCorpOverlay;
    private JButton overlayToggleButton;
    private boolean overlayEnabled = true;

    private PluginMode currentMode =
            PluginMode.BOOSTING;

    public ModePanel(
            WeCorpPanel boostingPanel,
            MassPanel massPanel,
            SoloPanel soloPanel,
            WeCorpOverlay weCorpOverlay,
            Consumer<PluginMode> modeChangedCallback)
    {
        this.modeChangedCallback =
                modeChangedCallback;
        this.weCorpOverlay = weCorpOverlay;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel selectorPanel =
                createSelectorPanel();

        cardPanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        cardPanel.add(
                boostingPanel,
                BOOSTING_CARD
        );


        cardPanel.add(
                soloPanel,
                SOLO_CARD
        );

        cardPanel.add(
                massPanel,
                MASS_CARD
        );
        add(selectorPanel, BorderLayout.NORTH);
        add(cardPanel, BorderLayout.CENTER);

        showMode(PluginMode.BOOSTING);
    }

    private JPanel createSelectorPanel()
    {
        JPanel selectorPanel =
                new JPanel(
                        new FlowLayout(
                                FlowLayout.CENTER,
                                4,
                                5
                        )
                );

        selectorPanel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        selectorPanel.setBorder(
                BorderFactory.createMatteBorder(
                        0,
                        0,
                        1,
                        0,
                        ColorScheme.MEDIUM_GRAY_COLOR
                )
        );

        selectorPanel.add(
                createModeButton(
                        PluginMode.BOOSTING,
                        "Boosting"
                )
        );

        selectorPanel.add(
                createModeButton(
                        PluginMode.SOLO,
                        "Solo"
                )
        );

        selectorPanel.add(
                createModeButton(
                        PluginMode.MASS,
                        "Mass"
                )
        );

        overlayToggleButton = new JButton();
        overlayToggleButton.setFocusable(false);
        overlayToggleButton.setFont(
                overlayToggleButton.getFont().deriveFont(
                        Font.BOLD,
                        10f
                )
        );
        overlayToggleButton.setBorder(
                BorderFactory.createEmptyBorder(
                        5,
                        7,
                        5,
                        7
                )
        );
        overlayToggleButton.setToolTipText(
                "Show or hide the WeCorpCC game overlay"
        );
        overlayToggleButton.addActionListener(event ->
        {
            overlayEnabled = !overlayEnabled;

            if (weCorpOverlay != null)
            {
                weCorpOverlay.setOverlayEnabled(
                        overlayEnabled
                );
            }

            refreshOverlayToggle();
        });

        selectorPanel.add(overlayToggleButton);
        refreshOverlayToggle();

        return selectorPanel;
    }

    private JButton createModeButton(
            PluginMode mode,
            String label)
    {
        JButton button =
                new JButton(label);

        button.setFocusable(false);

        button.setFont(
                button.getFont().deriveFont(
                        Font.BOLD,
                        10f
                )
        );

        button.setBorder(
                BorderFactory.createEmptyBorder(
                        5,
                        7,
                        5,
                        7
                )
        );

        button.addActionListener(event ->
        {
            if (modeChangedCallback != null)
            {
                modeChangedCallback.accept(mode);
            }
            else
            {
                showMode(mode);
            }
        });

        modeButtons.put(mode, button);

        return button;
    }

    public void showMode(PluginMode mode)
    {
        SwingUtilities.invokeLater(() ->
        {
            PluginMode safeMode =
                    mode == null
                            ? PluginMode.BOOSTING
                            : mode;

            currentMode = safeMode;
            switch (safeMode)
            {
                case MASS:
                    cardLayout.show(
                            cardPanel,
                            MASS_CARD
                    );
                    break;

                case SOLO:
                    cardLayout.show(
                            cardPanel,
                            SOLO_CARD
                    );
                    break;

                case BOOSTING:
                default:
                    cardLayout.show(
                            cardPanel,
                            BOOSTING_CARD
                    );
                    break;
            }

            refreshModeButtons();

            revalidate();
            repaint();
        });
    }

    private void refreshOverlayToggle()
    {
        if (overlayToggleButton == null)
        {
            return;
        }

        overlayToggleButton.setText(
                overlayEnabled
                        ? "Overlay ✓"
                        : "Overlay ✕"
        );

        overlayToggleButton.setForeground(
                overlayEnabled
                        ? ACTIVE_COLOR
                        : Color.RED
        );

        overlayToggleButton.setBackground(
                ColorScheme.MEDIUM_GRAY_COLOR
        );
    }

    private void refreshModeButtons()
    {
        for (Map.Entry<PluginMode, JButton> entry :
                modeButtons.entrySet())
        {
            boolean active =
                    entry.getKey() == currentMode;
            JButton button =
                    entry.getValue();

            String prefix =
                    active
                            ? "● "
                            : "○ ";

            String label;

            switch (entry.getKey())
            {
                case SOLO:
                    label = "Solo";
                    break;

                case MASS:
                    label = "Mass";
                    break;

                case BOOSTING:
                default:
                    label = "Boosting";
                    break;
            }

            button.setText(prefix + label);

            button.setForeground(
                    active
                            ? ACTIVE_COLOR
                            : INACTIVE_COLOR
            );

            button.setBackground(
                    active
                            ? ColorScheme.MEDIUM_GRAY_COLOR
                            : ColorScheme.DARKER_GRAY_COLOR
            );
        }
    }
}

package com.wecorpcc;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.NPCManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class WeCorpOverlay extends OverlayPanel
{
    private static final int CORP_REGION = 11844;
    private static final int CORP_ID = 319;

    private final Client client;
    private final NPCManager npcManager;
    private final WeCorpPlugin plugin;
    private final WeCorpConfig config;
    private boolean overlayEnabled = true;

    @Inject
    public WeCorpOverlay(
            Client client,
            NPCManager npcManager,
            WeCorpPlugin plugin,
            WeCorpConfig config)
    {
        this.client = client;
        this.npcManager = npcManager;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
    }

    void setOverlayEnabled(boolean enabled)
    {
        overlayEnabled = enabled;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!overlayEnabled)
        {
            return null;
        }

        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return null;
        }

        WorldPoint location = localPlayer.getWorldLocation();

        if (location == null ||
                location.getRegionID() != CORP_REGION)
        {
            return null;
        }

        NPC corp = findCorp();

        if (corp == null)
        {
            return null;
        }

        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text("WeCorpCC")
                        .build()
        );

        addCorpHp(corp);

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Your Damage")
                        .right(String.valueOf(
                                plugin.getLocalCorpDamage()))
                        .build()
        );

        /*
         * Boosting gets the full overlay.
         * Solo and Mass show HP only.
         */
        if (config.pluginMode() == PluginMode.BOOSTING)
        {
            int dwhTotal = plugin.getOverlayDwhCount();
            int maulTotal = plugin.getOverlayMaulCount();

            Actor target = corp.getInteracting();

            String targetName = "-";

            if (target instanceof Player &&
                    ((Player) target).getName() != null)
            {
                targetName = ((Player) target).getName();
            }

            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Target")
                            .right(targetName)
                            .build()
            );

            addLowestCustomerHp();

            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("DWH / Maul total")
                            .right(String.valueOf(
                                    dwhTotal + maulTotal))
                            .build()
            );
        }

        return super.render(graphics);
    }

    private NPC findCorp()
    {
        for (NPC npc : client.getNpcs())
        {
            if (npc != null &&
                    npc.getId() == CORP_ID)
            {
                return npc;
            }
        }

        return null;
    }

    private void addLowestCustomerHp()
    {
        Player lowestCustomer = null;
        double lowestPercent = 101.0;

        for (Player player : client.getPlayers())
        {
            if (player == null ||
                    player.getName() == null)
            {
                continue;
            }

            if (!plugin.isOverlayCustomer(
                    player.getName()))
            {
                continue;
            }

            int healthRatio =
                    player.getHealthRatio();

            int healthScale =
                    player.getHealthScale();

            if (healthRatio < 0 ||
                    healthScale <= 0)
            {
                continue;
            }

            double percentage =
                    (double) healthRatio /
                            healthScale *
                            100.0;

            if (percentage < lowestPercent)
            {
                lowestPercent = percentage;
                lowestCustomer = player;
            }
        }

        if (lowestCustomer == null)
        {
            return;
        }

        int displayPercent =
                (int) Math.round(
                        lowestPercent
                );

        boolean lowHp =
                displayPercent < 40;

        boolean flashOn =
                (System.currentTimeMillis() / 500) % 2 == 0;

        Color hpColor =
                lowHp && flashOn
                        ? Color.RED
                        : Color.WHITE;

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Client")
                        .right(
                                lowestCustomer.getName()
                        )
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("HP")
                        .right(
                                displayPercent + "%"
                        )
                        .rightColor(hpColor)
                        .build()
        );
    }
    private void addCorpHp(NPC corp)
    {
        int healthRatio = corp.getHealthRatio();
        int healthScale = corp.getHealthScale();

        if (healthRatio < 0 ||
                healthScale <= 0)
        {
            return;
        }

        Integer maxHealth = npcManager.getHealth(CORP_ID);

        if (maxHealth == null ||
                maxHealth <= 0)
        {
            return;
        }

        int health = 0;

        if (healthRatio > 0)
        {
            int minHealth = 1;
            int maxPossibleHealth;

            if (healthScale > 1)
            {
                if (healthRatio > 1)
                {
                    minHealth =
                            (maxHealth * (healthRatio - 1)
                                    + healthScale - 2)
                                    / (healthScale - 1);
                }

                maxPossibleHealth =
                        (maxHealth * healthRatio - 1)
                                / (healthScale - 1);

                if (maxPossibleHealth > maxHealth)
                {
                    maxPossibleHealth = maxHealth;
                }
            }
            else
            {
                maxPossibleHealth = maxHealth;
            }

            health =
                    (minHealth + maxPossibleHealth + 1) / 2;
        }

        double hpPercent =
                (double) health / maxHealth * 100.0;

        Color barColor;

        if (hpPercent > 60.0)
        {
            barColor = Color.GREEN;
        }
        else if (hpPercent > 30.0)
        {
            barColor = Color.YELLOW;
        }
        else
        {
            barColor = Color.RED;
        }

        ProgressBarComponent hpBar =
                new ProgressBarComponent();

        hpBar.setMinimum(0);
        hpBar.setMaximum(maxHealth);
        hpBar.setValue(health);

        hpBar.setForegroundColor(barColor);

        hpBar.setBackgroundColor(
                new Color(60, 20, 20)
        );

        hpBar.setCenterLabel(
                health + " / " + maxHealth
        );

        hpBar.setLabelDisplayMode(
                ProgressBarComponent.LabelDisplayMode.TEXT_ONLY
        );

        panelComponent.getChildren().add(hpBar);
    }
}
